describe('File Upload Button Disabled During Upload', () => {
  beforeEach(() => {
    cy.visit('/file-upload');
  });

  it('should disable upload button while file is uploading', () => {
    // Intercept the upload API call
    cy.intercept('POST', '/api/files/upload').as('uploadFile');

    // Verify upload button is enabled initially
    cy.get('[data-testid="upload-button"]').should('be.visible').should('not.be.disabled');

    // Select a file
    cy.get('[data-testid="file-input"]').selectFile('cypress/fixtures/sample.pdf');

    // Verify upload button is still enabled before clicking
    cy.get('[data-testid="upload-button"]').should('not.be.disabled');

    // Click upload button to start upload
    cy.get('[data-testid="upload-button"]').click();

    // Verify upload button is disabled during upload
    cy.get('[data-testid="upload-button"]').should('be.disabled');

    // Wait for the upload API call
    cy.wait('@uploadFile');

    // Verify upload button is re-enabled after upload completes
    cy.get('[data-testid="upload-button"]').should('not.be.disabled');

    // Verify success message is displayed
    cy.get('[data-testid="success-message"]').should('be.visible');
    cy.get('[data-testid="success-message"]').should('contain', 'File uploaded successfully');
  });

  it('should re-enable upload button if upload fails', () => {
    // Intercept the upload API call and force it to fail
    cy.intercept('POST', '/api/files/upload', {
      statusCode: 500,
      body: { error: 'Server error' }
    }).as('uploadFileFailed');

    // Verify upload button is enabled initially
    cy.get('[data-testid="upload-button"]').should('be.visible').should('not.be.disabled');

    // Select a file
    cy.get('[data-testid="file-input"]').selectFile('cypress/fixtures/sample.pdf');

    // Click upload button
    cy.get('[data-testid="upload-button"]').click();

    // Verify upload button is disabled during upload attempt
    cy.get('[data-testid="upload-button"]').should('be.disabled');

    // Wait for the failed upload API call
    cy.wait('@uploadFileFailed');

    // Verify upload button is re-enabled after failure
    cy.get('[data-testid="upload-button"]').should('not.be.disabled');

    // Verify error message is displayed
    cy.get('[data-testid="error-message"]').should('be.visible');
    cy.get('[data-testid="error-message"]').should('contain', 'Upload failed');
  });
});
